package algorithms.graphs;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class AStar {
public record Neighbor<N>(N node,double cost){}public record Result<N>(List<N> path,double cost){}public record AStarOptions<N>(N start,N goal,Function<N,Iterable<Neighbor<N>>> neighbors,ToDoubleFunction<N> heuristic,Function<N,Object> key){public AStarOptions(N start,N goal,Function<N,Iterable<Neighbor<N>>> neighbors,ToDoubleFunction<N> heuristic){this(start,goal,neighbors,heuristic,n->String.valueOf(n));}}private record Entry<N>(N node,double cost,double estimate){}public static <N> Result<N> aStar(AStarOptions<N> opts){Object goal=opts.key.apply(opts.goal);Map<Object,Double> best=new HashMap<>();Map<Object,N> came=new HashMap<>();data_structures.heaps.BinaryHeap.Heap<Entry<N>> open=new data_structures.heaps.BinaryHeap.Heap<>(Comparator.comparingDouble(Entry::estimate));best.put(opts.key.apply(opts.start),0.0);open.push(new Entry<>(opts.start,0,opts.heuristic.applyAsDouble(opts.start)));while(!open.isEmpty()){Entry<N> e=open.pop();Object k=opts.key.apply(e.node);if(e.cost>best.get(k))continue;if(Objects.equals(k,goal)){List<N> p=new ArrayList<>();p.add(e.node);for(N c=came.get(k);c!=null;c=came.get(opts.key.apply(c)))p.add(c);Collections.reverse(p);return new Result<>(p,e.cost);}for(Neighbor<N> next:opts.neighbors.apply(e.node)){Object nk=opts.key.apply(next.node);double nc=e.cost+next.cost;if(nc<best.getOrDefault(nk,Double.POSITIVE_INFINITY)){best.put(nk,nc);came.put(nk,e.node);open.push(new Entry<>(next.node,nc,nc+opts.heuristic.applyAsDouble(next.node)));}}}return null;}public record Cell(int row,int col){}public static List<Cell> aStarGrid(List<String> g,Cell s,Cell t){return aStarGrid(g,s,t,'#');}public static List<Cell> aStarGrid(List<String> g,Cell s,Cell t,char wall){int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};Result<Cell> r=aStar(new AStarOptions<>(s,t,c->{List<Neighbor<Cell>> n=new ArrayList<>();for(int[] d:dirs){int row=c.row+d[0],col=c.col+d[1];if(row>=0&&row<g.size()&&col>=0&&col<g.get(row).length()&&g.get(row).charAt(col)!=wall)n.add(new Neighbor<>(new Cell(row,col),1));}return n;},c->Math.abs(c.row-t.row)+Math.abs(c.col-t.col),c->c));return r==null?null:r.path;}
}
